<template>
  <el-dialog
    :title="title"
    :visible.sync="visible"
    :width="width"
    :center="true"
    :modal="false"
    :fullscreen="isMobile ? true : fullscreen"
    :top="dTop"
    @close="onDialogClose"
    class="marker-dialog-wrapper"
    :class="isMobile ? 'marker-mobile-dialog-wrapper' : ''"
    :destroy-on-close="true"
  >
    <div class="marker-dialog">
      <div class="marker-dialog-body">
        <div
          class="text-marker"
          v-if="markerInfo && markerInfo.hotType === 'text'"
        >
          <div class="text-marker-content">{{ markerInfo.content }}</div>
        </div>
        <div
          class="images-marker"
          v-if="markerInfo && markerInfo.hotType === 'image'"
        >
          <swiper
            ref="mySwiper"
            :options="swiperOptions"
            class="img-dialog-swiper"
          >
            <swiper-slide v-for="(slide, key) in markerInfo.imgUrls" :key="key">
              <div align="center">
                <img :src="slide" alt class="swiper-img" />
              </div>
            </swiper-slide>
            <div class="swiper-pagination" slot="pagination"></div>
          </swiper>
        </div>
        <div
          class="video-marker"
          v-if="markerInfo && markerInfo.hotType === 'video'"
        >
          <EasyPlayer
            :videoUrl="markerInfo.videoUrl"
            ref="eplayer"
            :aspect="aspect"
            :onDemand="true"
            :autoplay="autoplay"
            :muted="muted"
            element-loading-text="加载中..."
            element-loading-background="#000"
            :fluent="fluent"
            :stretch="stretch"
            :live="live"
            @error="onPlayError"
            class="player"
          />
        </div>
      </div>
    </div>
  </el-dialog>
</template>
<script>
import EasyPlayer from '@easydarwin/easyplayer'
import { Swiper, SwiperSlide, directive } from 'vue-awesome-swiper'
import { isMobile } from '@/utils/tools'
import 'swiper/css/swiper.css'
export default {
  name: 'MarkerShow',
  components: {
    EasyPlayer,
    Swiper,
    SwiperSlide,
  },
  directives: {
    swiper: directive,
  },
  data() {
    return {
      markerInfo: null,
      title: '',
      width: '760px',
      visible: false,
      fullscreen: false,
      dTop: '',

      videoUrl: '',
      mode: '4',
      aspect: '16:9',
      muted: false,
      autoplay: false,
      fluent: false,
      stretch: false,
      live: false,

      swiperShow: false,
      swiperOptions: {
        autoplay: {
          disableOnInteraction: false, // 用户操作swiper之后，是否禁止autoplay
          delay: 3000, // 自动切换的时间间隔（单位ms）
        },
        initialSlide: 0,
        loop: true,
        pagination: { el: '.swiper-pagination' }, // 分页按钮
        paginationClickable: true,
      },
      swiperList: [],
    }
  },
  computed: {
    swiper() {
      if (this.$refs.mySwiper) {
        return this.$refs.mySwiper.$swiper
      }
      return null
    },
    isMobile() {
      return isMobile()
    },
  },
  methods: {
    open(markerInfo, dialogWidth = '760px', fullscreen = false, dTop = '4vh') {
      this.markerInfo = markerInfo
      console.log('markerInfo:', markerInfo)
      this.title = markerInfo.title || null
      this.fullscreen = fullscreen
      this.dTop = dTop
      this.width = dialogWidth
      this.visible = true
      if (this.markerInfo.hotType === 'video' && this.markerInfo.videoUrl) {
        if (
          this.markerInfo.videoUrl.indexOf('.m3u8') >= 0 ||
          this.markerInfo.videoUrl.indexOf('.flv') >= 0
        ) {
          this.muted = true
          this.live = true
          this.$nextTick(() => {
            this.autoplay = true
          })
        }
        return true
      }
    },
    onPlayError() {},
    onDialogClose() {
      this.$emit('onDialogClose')
      if (this.$refs.eplayer) {
        this.$refs.eplayer.destroyPlayer()
      }
    },
  },
}
</script>
